const { Client, Collection, Events, GatewayIntentBits } = require("discord.js");
const fs = require("fs");
const path = require("path");

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.commands = new Collection();

const commandsPath = path.join(__dirname, "commands");
const commandFiles = fs
  .readdirSync(commandsPath)
  .filter((file) => file.endsWith(".js"));

for (const file of commandFiles) {
  const filePath = path.join(commandsPath, file);
  const command = require(filePath);
  client.commands.set(command.data.name, command);
}

client.once(Events.ClientReady, () => {
  console.log(`Bot is ready. Logged in as ${client.user.tag}`);
});

client.on(Events.InteractionCreate, async (interaction) => {
  if (!interaction.isCommand()) return;

  const command = client.commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    return interaction.reply({
      content: "There was an error while executing this command.",
      ephemeral: true,
    });
  }
});

client.login("YOUR_BOT_TOKEN_HERE");
```
1. Create a `commands` folder in the same directory as the `main.js` file.
2. Create a new file named `ban.js` in the `commands` folder and add the following code:
```javascript
const { SlashCommandBuilder } = require("discord.js");
const { Permissions } = require("discord.js");

module.exports = {
  data: new SlashCommandBuilder()
    .setName("ban")
    .setDescription("Ban a user from the server.")
    .addUserOption((option) =>
      option
        .setName("target")
        .setDescription("The user to be banned from the server")
    )
    .addStringOption((option) =>
      option
        .setName("reason")
        .setDescription("The reason for the ban (Optional)")
    )
    .addIntegerOption((option) =>
      option
        .setName("days")
        .setDescription("Number of days the ban will last (Optional)")
    ),
  async execute(interaction) {
    const target = interaction.options.get("target");
    const reason = interaction.options.get("reason")
      ? interaction.options.get("reason").value
      : "No reason provided.";
    const days = interaction.options.get("days")
      ? interaction.options.get("days").value
      : 7;

    if (
      !interaction.member.permissions.has(Permissions.FLAGS.BAN_MEMBERS)
    ) {
      return interaction.reply({
        content: "You can't ban members because you don't have the required permissions.",
        ephemeral: true,
      });
    }

    if (target.user.id === interaction.user.id) {
      return interaction.reply({
        content: "You can't ban yourself.",
        ephemeral: true,
      });
    }

    if (target.user.id === interaction.guild.ownerId) {
      return interaction.reply({
        content: "You can't ban the server owner.",
        ephemeral: true,
      });
    }

    if (target.user.id === client.user.id) {
      return interaction.reply({
        content: "You can't ban the bot.",
        ephemeral: true,
      });
    }

    try {
      const banned = await interaction.guild.bans.create({
        user: target.user,
        days: days,
        reason: reason,
      });

      return interaction.reply({
        content: `Successfully banned ${target.user.tag}.`,
        ephemeral: true,
      });
    } catch (error) {
      console.error(error);
      return interaction.reply({
        content: "An error occurred while trying to ban the user.",
        ephemeral: true,
      });
    }
  },
};
```
