std::string convertMarkdownToHTML(const std::string& markdown) {
    // Define regular expression patterns for different markdown elements
    std::regex headingPattern("#+(\\S.*)");
    std::regex linkPattern("(\\*(\\S.*?)\\*)");
    std::regex listPattern("(?ims)(?:\\*|\\d\\.)\\s+(\\S.*)");

    // Create an output string stream to accumulate the HTML content
    std::stringstream htmlStream;

    // Replace the markdown elements with their corresponding HTML elements
    std::regex_replace(std::ostream_iterator<std::string>(htmlStream),
                       markdown.cbegin(),
                       markdown.cend(),
                       headingPattern,
                       [](const std::smatch& match) {
                           // For headings, add a <h1> or <h2> tag based on the number of '#' characters
                           int level = match.str().length() - match.str().find_last_not_of("#") - 1;
                           return std::string("<h") + std::to_string(level) + ">" + match.str() + "</h" + std::to_string(level) + ">";
                       });

    // Replace links
    std::regex_replace(htmlStream, linkPattern, "<a href=\"\\1\">\\1</a>");

    // Replace lists
    std::regex_replace(htmlStream, listPattern, "<li>$1</li>");

    // Convert the string stream to a single string
    std::string htmlString = htmlStream.str();

    // Add the opening and closing <ul> and <ol> tags for lists
    std::regex listStartPattern("(<li>\\S.*</li>)", std::regex_constants::format_all);
    std::regex listTypePattern("(?ims)(?:\\*|\\d\\.)", std::regex_constants::format_first_not_captured);
    std::regex listEndTag("(<li>\\S.*</li>)", std::regex_constants::format_first_not_captured);

    // Add <ul> or <ol> tags for each list
    std::regex_replace(htmlString.begin(),
                       htmlString.end(),
                       htmlString.begin(),
                       listStartPattern,
                       [](const std::smatch& match) {
                           // Check if the list item starts with a '*' or a digit
                           std::string listType = std::regex_replace(match.str(), listTypePattern, "");
                           if (listType.empty()) {
                               return "<ul>" + match.str() + "</ul>";
                           } else {
                               return "<ol>" + match.str() + "</ol>";
                           }
                       });

    // Add </ul> or </ol> for each list
    std::regex_replace(htmlString.begin(),
                       htmlString.end(),
                       htmlString.begin(),
                       listEndTag,
                       [](const std::smatch& match) {
                           return "</" + std::string(match.str().begin() + 1, match.str().end() - 1) + ">";
                       });

    return htmlString;
}
