// Helper function to check if a number is prime
function isPrime(num) {
  // Check if the number is less than 2 or not
  if (num < 2) {
    return false;
  }

  // Check if the number is divisible by any number in the range of 2 to the square root of the number
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false;
    }
  }

  // If no factor is found, the number is prime
  return true;
}
