Title: Optimal Binary Search Tree using Dynamic Programming

Problem Description:
--------------------

Given a list of distinct integers, construct the optimal Binary Search Tree (BST) that minimizes the sum of the distances of each element to its nearest leaf node.

Example:
---------

For the list `[1, 3, 4, 2, 5]`, the optimal BST is:
```
   2
  / \
 1   4
   / \
  3   5
```
Input Format:
-------------

The input contains a list of distinct positive integers.

Example Input:
--------------

1 3 4 2 5

Output Format:
--------------

The output should contain a space-separated list of integers representing the in-order traversal of the optimal BST.

Example Output:
----------------

2 1 3 4 5

Constraints:
------------

1 <= number of elements <= 1000
1 <= element value <= 1000

Sample Code:
------------

```
#include <iostream>
#include <vector>
using namespace std;

// A function to calculate the sum of distances of a given set of elements
int calculateSumOfDistances(vector<int>& set, int i, int j, int parent)
{
    // If the set has only one element, return 0
    if (i == j)
    {
        return 0;
    }
    int mid = (i + j) / 2;
    int leftSum = calculateSumOfDistances(set, i, mid, set[mid]);
    int rightSum = calculateSumOfDistances(set, mid + 1, j, set[mid]);
    int leftSize = mid - i + 1;
    int rightSize = j - mid;
    int leftDistance = 0, rightDistance = 0;
    for (int k = i; k <= j; k++)
    {
        // Calculate the distance of each element in the set to its nearest leaf
        if (k < mid)
        {
            leftDistance += (set[k] - parent);
        }
        else
        {
            rightDistance += (parent - set[k]);
        }
    }
    return min(leftSum, rightSum) + leftDistance + rightDistance;
}

int main()
{
    int n, i;
    cin >> n;
    vector<int> set(n);
    for (i = 0; i < n; i++)
    {
        cin >> set[i];
    }
    int minSum = calculateSumOfDistances(set, 0, n - 1, set[0]);
    cout << set[0];
    for (i = 1; i < n; i++)
    {
        cout << " " << set[i];
    }
    return 0;
}
