Problem Description:
--------------------

Given a string of mathematical expressions containing only the operations of addition, subtraction, and multiplication represented by '+' (plus), '-' (minus), and '\*' (asterisk), find the optimal way to add parentheses to the expression to minimize the result.

Example:
---------

For the string `22+9*3`, the optimal way to add parentheses is `(22+(9*3))`, which results in the minimum value of `53`.

Input Format:
-------------

The input contains a string of mathematical expressions.

Example Input:
--------------

22+9\*3

Output Format:
--------------

The output should contain a string representing the expression with the optimal parenthesization.

Example Output:
----------------

(22+(9\*3))

Constraints:
------------

1 <= length of the input string <= 1000
The input string will only contain the characters '0-9', '+', '-' and '\*'

Sample Code:
------------

```
#include <iostream>
#include <string>
using namespace std;

// A function to calculate the minimum value of a given expression
int calculateMinimumValue(string expression, int start, int end)
{
    // If the expression is a single number, return the value
    if (start == end)
    {
        return stoi(expression.substr(start, end - start + 1));
    }
    // Create a 2D vector to store the results of sub-expressions
    vector<vector<int>> results(end - start + 1, vector<int>(end - start + 1, -1));
    int min = INT_MAX;
    // Iterate through the possible positions to add a single pair of parentheses
    for (int i = start + 1; i < end; i++)
    {
        // If the sub-expressions on both sides of the parentheses have already been calculated
        if (results[start][i - 1] != -1 && results[i][end] != -1)
        {
            int value = calculateMinimumValue(expression, start, i - 1) +
                        calculateMinimumValue(expression, i, end) +
                        (expression[i] == '+' ? (results[start][i - 1] + results[i][end]) :
                         (results[start][i - 1] - results[i][end]));
            min = min(min, value);
        }
    }
    return min;
}

