Title: Longest Palindromic Subsequence using Dynamic Programming

Problem Description:
--------------------

Given a string, find the length of the longest palindromic subsequence in it. A palindromic subsequence is a sequence that reads the same backward and forward.

Example:
---------

For the string "anagram", the longest palindromic subsequence is "an", "na", or "gn", with a length of 2.

Input Format:
-------------

The input contains a string.

Example Input:
--------------

anagram

Output Format:
--------------

The output should contain a single integer representing the length of the longest palindromic subsequence.

Example Output:
----------------

2

Constraints:
------------

1 <= length of the input string <= 1000
The input string will only contain lowercase English alphabets.

Sample Code:
------------

```
#include <iostream>
#include <string>
using namespace std;

// A function to calculate the length of the longest palindromic subsequence
int calculateLongestPalindrome(string str, int n)
{
    // Create a 2D vector to store the results
    vector<vector<int>> dp(n, vector<int>(n, 0));
    // Base case: If the string is empty or has a single character, the palindromic subsequence is also empty
    for (int i = 0; i < n; i++)
    {
        dp[i][i] = 1;
    }
    // Check for palindromic subsequences of length 2
    for (int i = 0; i < n - 1; i++)
    {
        if (str[i] == str[i + 1])
        {
            dp[i][i + 1] = 2;
        }
    }
    // Check for palindromic subsequences of length > 2
    for (int l = 3; l <= n; l++)
    {
        for (int i = 0; i < n - l + 1; i++)
        {
            int j = i + l - 1;
            if (str[i] == str[j] && dp[i + 1][j - 1] != 0)
            {
                dp[i][j] = dp[i + 1][j - 1] + 2;
            }
            else
            {
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);
            }
        }
    }
    return dp[0][n - 1];
}

int main()
{
    string str;
    cin >> str;
    int length = calculateLongestPalindrome(str, str.length());
    cout << length;
    return 0;
}
