Title: Matrix Chain Multiplication with Caching using Dynamic Programming

Problem Description:
--------------------

Given a list of matrices with their dimensions, find the optimal order of matrix multiplications to minimize the total number of multiplications.

Example:
---------

For the list of matrices with dimensions `[2, 3, 4, 5, 6]`, the optimal order of multiplication is `(2x3) x (4x5) x (6x4)`, with a total of 11 multiplications.

Input Format:
-------------

The input contains a list of positive integers representing the dimensions of the matrices in the chain.

Example Input:
--------------

2 3 4 5 6

Output Format:
--------------

The output should contain a space-separated list of integers representing the optimal order of matrix multiplications.

Example Output:
----------------

1 2 3

Constraints:
------------

1 <= number of matrices <= 1000
1 <= dimension of any matrix <= 1000

Sample Code:
------------

```
#include <iostream>
#include <vector>
using namespace std;

// A function to calculate the minimum number of multiplications for a given set of matrix dimensions
int calculateMinimumMultiplications(vector<int>& dimensions, int start, int end, vector<vector<int>>& cache)
{
    // If the sub-problem has already been solved, return the result from the cache
    if (cache[start][end] != -1)
    {
        return cache[start][end];
    }
    // If the sub-problem has only one or two matrices, the optimal order is to multiply them in the given order
    if (end - start <= 1)
    {
        return cache[start][end] = 0;
    }
    int minMultiplications = INT_MAX;
    // Iterate through the possible break points to split the sub-problem
    for (int i = start; i < end; i++)
    {
        int left = calculateMinimumMultiplications(dimensions, start, i, cache);
        int right = calculateMinimumMultiplications(dimensions, i + 1, end, cache);
        int current = dimensions[start - 1] * dimensions[i] * dimensions[end];
        minMultiplications = min(minMultiplications, left + right + current);
    }
    return cache[start][end] = minMultiplications;
}

int main()
{
    int n, i;
    cin >> n;
    vector<int> dimensions(n);
    for (i = 0; i < n; i++)
    {
        cin >> dimensions[i];
    }
    // Create a 2D vector to store the results of sub-problems
    vector<vector<int>> cache(n, vector<int>(n, -1));
    int minMultiplications = calculateMinimumMultiplications(dimensions, 1, n, cache);
    // Print the optimal order of matrix multiplications
    cout << "1";
    for (int i = 1; i < n; i++)
    {
        cout << " " << i + 1;
    }
    return 0;
}
